  /** Atomically applies a coupon: updates the order, records the redemption and bumps usage. */
  applyCoupon(id: number, couponCode: string, discountCents: number, createdAt: string): Order {
    this.db.exec("BEGIN");
    try {
      this.db
        .prepare(
          `UPDATE orders
              SET discount_cents = ?, final_amount_cents = amount_cents - ?, coupon_code = ?
            WHERE id = ?`,
        )
        .run(discountCents, discountCents, couponCode, id);
      this.db
        .prepare(
          `INSERT INTO coupon_redemptions (order_id, coupon_code, discount_cents, created_at)
           VALUES (?, ?, ?, ?)`,
        )
        .run(id, couponCode, discountCents, createdAt);
      this.db.prepare("UPDATE coupons SET used_count = used_count + 1 WHERE code = ?").run(couponCode);
      this.db.exec("COMMIT");
    } catch (e) {
      this.db.exec("ROLLBACK");
      throw e;
    }
    return this.findById(id)!;
  }
}

